static class Palette {
    public static Color Ink=Color.FromArgb(66,42,53),Muted=Color.FromArgb(150,116,129),Accent=Color.FromArgb(185,66,95),Background=Color.FromArgb(253,245,247),Line=Color.FromArgb(240,219,225),Rail=Color.FromArgb(62,34,49);
    public static Color Tint=Color.FromArgb(254,248,250),Soft=Color.FromArgb(253,240,245);
    public static GraphicsPath Round(Rectangle r,int radius){var p=new GraphicsPath();int d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}
class Card : Panel {
    public Card(){DoubleBuffered=true;BackColor=Palette.Background;Padding=new Padding(20);}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Palette.Round(new Rectangle(0,0,Width-1,Height-1),15)){using(var fill=new SolidBrush(Color.White))e.Graphics.FillPath(fill,path);using(var pen=new Pen(Palette.Line))e.Graphics.DrawPath(pen,path);}using(var brush=new SolidBrush(Color.FromArgb(45,Palette.Accent)))e.Graphics.FillEllipse(brush,Width-43,12,7,7);}
}
class SoftButton : Button {
    public bool Primary,Dark;bool hover;
    public SoftButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;AutoSize=false;Height=38;Margin=new Padding(0,0,8,0);}
    protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.Clear(Parent==null?Palette.Background:Parent.BackColor);Color fill=Primary?(Enabled?Palette.Accent:MainForm.BlendColor(Palette.Accent,Color.White,.4f)):Dark?(hover?MainForm.BlendColor(Palette.Rail,Palette.Accent,.75f):Palette.Rail):(hover?MainForm.BlendColor(Palette.Accent,Color.White,.17f):Palette.Soft);Color text=Primary||Dark?Color.White:Enabled?Palette.Ink:Palette.Muted;using(var path=Palette.Round(new Rectangle(0,0,Width-1,Height-1),9)){using(var brush=new LinearGradientBrush(ClientRectangle,Primary?MainForm.BlendColor(fill,Color.White,.84f):fill,fill,70))e.Graphics.FillPath(brush,path);if(!Primary&&!Dark)using(var pen=new Pen(Palette.Line))e.Graphics.DrawPath(pen,path);}TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,text,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);if(Focused){using(var pen=new Pen(Color.FromArgb(90,Palette.Accent))){pen.DashStyle=DashStyle.Dot;e.Graphics.DrawRectangle(pen,4,4,Width-9,Height-9);}}}
}
class BrandMark : Control {
    public BrandMark(){Size=new Size(48,48);SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
    public static void Draw(Graphics g,Rectangle box){g.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Palette.Round(box,Math.Max(4,box.Width/4))){using(var b=new LinearGradientBrush(box,Color.FromArgb(220,117,143),Color.FromArgb(166,46,79),45))g.FillPath(b,path);}float s=box.Width/64f;var state=g.Save();g.TranslateTransform(box.X,box.Y);g.ScaleTransform(s,s);using(var pen=new Pen(Color.White,4f)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawBezier(pen,12,17,24,21,40,21,52,17);g.DrawLine(pen,16,28,48,28);g.DrawLine(pen,23,22,21,49);g.DrawLine(pen,41,22,43,49);}using(var brush=new SolidBrush(Color.White))g.FillPolygon(brush,new PointF[]{new PointF(29,33),new PointF(29,43),new PointF(37,38)});g.Restore(state);}
    protected override void OnPaint(PaintEventArgs e){Draw(e.Graphics,new Rectangle(1,1,Width-2,Height-2));}
}
class ShrineRail : Panel {
    readonly Timer animation=new Timer();float phase;bool animate=true;public bool Animate{get{return animate;}set{animate=value;Invalidate();}}public int ThemeIndex;
    public ShrineRail(){DoubleBuffered=true;animation.Interval=60;animation.Tick+=delegate{if(Animate&&Visible){phase+=1.8f;Invalidate();}};animation.Start();}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;int y=Math.Max(490,Height-265);using(var pen=new Pen(Color.FromArgb(55,Palette.Accent),ThemeIndex==0?5:2)){
        if(ThemeIndex==0){g.DrawBezier(pen,22,y,72,y+13,117,y+13,166,y);g.DrawLine(pen,31,y+25,157,y+25);g.DrawLine(pen,53,y+8,49,y+130);g.DrawLine(pen,135,y+8,139,y+130);}
        else if(ThemeIndex==2){g.DrawEllipse(pen,25,y,138,138);g.DrawEllipse(pen,36,y+11,116,116);PointF[] star=new PointF[5];for(int j=0;j<5;j++){double a=(-90+j*144)*Math.PI/180;star[j]=new PointF(94+(float)Math.Cos(a)*58,y+69+(float)Math.Sin(a)*58);}g.DrawPolygon(pen,star);}
        else if(ThemeIndex==3){g.DrawEllipse(pen,48,y,92,92);g.DrawArc(pen,73,y-2,92,92,90,180);}
    }
    for(int i=0;i<15;i++){float px=10+(i*53)%Math.Max(20,Width-25)+(float)Math.Sin((phase+i*41)/70)*12;float py=(phase+i*71)%Math.Max(1,Height);var state=g.Save();g.TranslateTransform(px,py);g.RotateTransform(i*31+phase*.35f);using(var pen=new Pen(Color.FromArgb(90,MainForm.BlendColor(Palette.Accent,Color.White,.45f)),1.2f))using(var b=new SolidBrush(Color.FromArgb(75,MainForm.BlendColor(Palette.Accent,Color.White,.45f)))){
        if(ThemeIndex==1){for(int j=0;j<3;j++){var s=g.Save();g.RotateTransform(j*60);g.DrawLine(pen,0,-6,0,6);g.DrawLine(pen,0,-3,-2,-5);g.DrawLine(pen,0,3,2,5);g.Restore(s);}}
        else if(ThemeIndex==2){g.DrawLine(pen,-4,0,4,0);g.DrawLine(pen,0,-4,0,4);g.FillEllipse(b,-1,-1,2,2);}
        else if(ThemeIndex==4){Color[] rainbow={Color.Gold,Color.Salmon,Color.LightSkyBlue,Color.Plum,Color.PaleGreen};using(var gem=new SolidBrush(Color.FromArgb(120,rainbow[i%5])))g.FillPolygon(gem,new Point[]{new Point(0,-7),new Point(4,0),new Point(0,7),new Point(-4,0)});}
        else{using(var p=new GraphicsPath()){p.AddBezier(0,-6,8,-5,8,3,0,7);p.AddBezier(0,7,-4,0,-6,-3,0,-6);g.FillPath(b,p);}}
    }g.Restore(state);}}
    protected override void Dispose(bool disposing){if(disposing)animation.Dispose();base.Dispose(disposing);}
}
class ReimuBanner : Panel {
    Image illustration;
    public ReimuBanner(){DoubleBuffered=true;using(var stream=typeof(MainForm).Assembly.GetManifestResourceStream("Reimu.banner")){if(stream!=null)using(var img=Image.FromStream(stream))illustration=new Bitmap(img);}}
    public void SetArtwork(Image image){var previous=illustration;illustration=image;if(previous!=null)previous.Dispose();Invalidate(true);}
    protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(Palette.Background);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Palette.Round(new Rectangle(0,0,Width-1,Height-1),16)){var saved=e.Graphics.Save();e.Graphics.SetClip(path);if(illustration!=null){float scale=Math.Max((float)Width/illustration.Width,(float)Height/illustration.Height);float w=illustration.Width*scale,h=illustration.Height*scale;e.Graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;e.Graphics.DrawImage(illustration,new RectangleF((Width-w)/2,(Height-h)/2,w,h));}using(var wash=new LinearGradientBrush(new Rectangle(0,0,Width,Height),Color.FromArgb(155,255,248,243),Color.FromArgb(0,255,248,243),0f))e.Graphics.FillRectangle(wash,0,0,Width*2/3,Height);e.Graphics.Restore(saved);using(var pen=new Pen(Palette.Line))e.Graphics.DrawPath(pen,path);}}
    protected override void Dispose(bool disposing){if(disposing&&illustration!=null)illustration.Dispose();base.Dispose(disposing);}
}
