    void ShowAccount(){
        using(var dialog=new Form{Text="映拾 · 账号与登录",ClientSize=new Size(560,350),Font=Font,BackColor=Palette.Background,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){
            var card=new Card{Dock=DockStyle.Fill,Margin=new Padding(16)};dialog.Padding=new Padding(20);dialog.Controls.Add(card);var grid=Grid(1,5);int[] heights={40,50,42,60,55};foreach(int h in heights)grid.RowStyles.Add(new RowStyle(SizeType.Absolute,h));card.Controls.Add(grid);grid.Controls.Add(CopyLabel("登录，获取账号可用的画质",15,true));grid.Controls.Add(new Label{Text="网页使用常规扫码登录，TV 模式使用 TV 扫码登录。\n需要手动填写时，也可以在下方输入 Cookie。",AutoSize=true,ForeColor=Palette.Muted});var input=new TextBox{Text=cookie.Text,UseSystemPasswordChar=true};grid.Controls.Add(TextField(input));var choices=Row();choices.BackColor=Color.White;choices.Controls.Add(ActionButton("网页扫码",async delegate{cookie.Text=input.Text;dialog.Close();await Run(false,true);},true));choices.Controls.Add(Btn("TV 扫码",async delegate{cookie.Text=input.Text;dialog.Close();commandOverride="logintv";try{await Run(false,true);}finally{commandOverride=null;}}));choices.Controls.Add(Btn("保存并返回",delegate{cookie.Text=input.Text;dialog.Close();}));grid.Controls.Add(choices);grid.Controls.Add(new Label{Text="Cookie 只保留在本次运行中。登录凭据由 BBDown 管理。",ForeColor=Palette.Muted,AutoSize=true,Font=new Font(Font.FontFamily,9)});dialog.ShowDialog(this);
        }
    }
}
